            local pr = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
            local car = vf and vf:FindFirstChild(p.Name)
            local cr = car and (car:FindFirstChild("Weight") or car.PrimaryPart)
            if pr then out[#out + 1] = pr.Position end
            if cr then out[#out + 1] = cr.Position end
        end
    end
    return out
end
function A.beingArrested()
    local c = lp.Character
    return num(lp:GetAttribute("ArrestCirclePercentage")) > 0 or (c and num(c:GetAttribute("ArrestCirclePercentage")) > 0) or false
end
function A.danger()
    if not S.flee then return false end
    if A.beingArrested() then return true, nil end
    local me = lp.Character and lp.Character:GetPivot().Position
    if not me then return false end
    local best, bd
    for _, c in ipairs(A.copList()) do
        local d = (c - me).Magnitude
        if d <= S.fleeDist and (not bd or d < bd) then best, bd = c, d end
    end
    return best ~= nil, best
end
function A.exitCar()
    local h = hum()
    if not h then return end
    if h.SeatPart then
        h.Sit = false
        pcall(function() h:ChangeState(Enum.HumanoidStateType.Jumping) end)
        local t0 = os.clock()
        while h.SeatPart and os.clock() - t0 < 2 do task.wait(0.05) end
        task.wait(0.15)
    end
end
function A.walkTo(pos, within, alive)
    local h = hum()
    if not h then return false end
    if A.charDist(pos) <= within then return true end
    h:MoveTo(pos)
    local t0 = os.clock()
    while alive() and os.clock() - t0 < 3 and A.charDist(pos) > within do task.wait(0.1) end
    if alive() and A.charDist(pos) > within then T.go(pos + Vector3.new(0, 2.5, 0), { alive = alive, ground = true, tol = 2, speed = 40 }) end
    return A.charDist(pos) <= within
end
function A.toCar()
    if inCar() then return true end
    if myCar() then return sitInCar() end
    return ensureCar(true)
end
function A.unanchor()
    local r = A.anch
    A.anch = nil
    if r and r.Parent then pcall(function() r.Anchored = false end) end
end
onClean(A.unanchor)
function A.groundAt(pos)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local ex = { lp.Character }
    local vf = workspace:FindFirstChild("Vehicles")
    if vf then ex[#ex + 1] = vf end
    params.FilterDescendantsInstances = ex
    params.RespectCanCollide = true
    local hit = workspace:Raycast(pos + Vector3.new(0, 6, 0), Vector3.new(0, -40, 0), params)
    if hit and hit.Material ~= Enum.Material.Water then return hit.Position.Y end
    return nil
end
function A.tp(pos, alive)
    local h = hum()
    if h and h.SeatPart then
        h.Sit = false
        pcall(function() h:ChangeState(Enum.HumanoidStateType.Jumping) end)
        local t0 = os.clock()
        while h.SeatPart and os.clock() - t0 < 1.5 do task.wait(0.05) end
    end
    local r = hrp()
    if not r then return false end
    if h then h.PlatformStand = false end
    local far = (r.Position - pos).Magnitude > 150
    local back = r.CFrame
    A.unanchor()
    r.AssemblyLinearVelocity = Vector3.zero
    r.AssemblyAngularVelocity = Vector3.zero
    r.CFrame = CFrame.new(pos + Vector3.new(0, 4, 0))
    r.Anchored = true
    A.anch = r
    local done = not far
    if far then task.spawn(function() T.stream(pos) done = true end) end
    local y
    local t0 = os.clock()
    while os.clock() - t0 < 6 do
        if alive and not alive() then break end
        if not r.Parent then break end
        y = A.groundAt(pos)
        if y and (done or os.clock() - t0 > 0.3) then break end
        task.wait(0.1)
    end
    if r.Parent then
        if y then r.CFrame = CFrame.new(pos.X, y + 3, pos.Z) elseif not alive or alive() then r.CFrame = back end
        r.AssemblyLinearVelocity = Vector3.zero
    end
    A.unanchor()
    return y ~= nil
end
function A.loadFile(file, into)
    pcall(function()
        if isfile and readfile and isfile(file) then
            local list = HttpService:JSONDecode(readfile(file))
            for i, v in ipairs(type(list) == "table" and list or {}) do
                if type(v) == "table" and tonumber(v[1]) and tonumber(v[2]) and tonumber(v[3]) then
                    into["file" .. i] = Vector3.new(v[1], v[2], v[3])
                end
            end
        end
    end)
end
function A.saveFile(file, from)
    if not writefile then return end
    local list, have = {}, {}
    for _, p in pairs(from) do
        local key = math.floor(p.X / 8) .. "," .. math.floor(p.Z / 8)
        if not have[key] then
            have[key] = true
            list[#list + 1] = { math.floor(p.X * 10) / 10, math.floor(p.Y * 10) / 10, math.floor(p.Z * 10) / 10 }
        end
    end
    pcall(function() writefile(file, HttpService:JSONEncode(list)) end)
end
function A.uniq(from)
    local out, have = {}, {}
    for _, p in pairs(from) do
        local key = math.floor(p.X / 8) .. "," .. math.floor(p.Z / 8)
        if not have[key] then have[key] = true out[#out + 1] = p end
    end
    return out
end
function A.key(p) return math.floor(p.X / 10) .. "," .. math.floor(p.Z / 10) end
A.file = "cw_de_atm_spots.json"
A.dropFile = "cw_de_drop_spots.json"
A.drops = {}
A.known = {}
A.loadFile(A.file, A.seen)
A.loadFile(A.dropFile, A.drops)
function A.saveSpots()
    if os.clock() - (A.savedAt or 0) < 20 then return end
    A.savedAt = os.clock()
    A.saveFile(A.file, A.seen)
end
function A.spawners()
    local sp = find(workspace, "Game.Jobs.CriminalATMSpawners")
    local added = false
    for _, d in ipairs(sp and sp:GetChildren() or {}) do
        if d.Name ~= "CriminalATMSpawnerWater" then
            local ok, p = pcall(function() return d:IsA("BasePart") and d.Position or d:GetPivot().Position end)
            local key = ok and p and (d:GetAttribute("ComponentServerId") or d:GetFullName() .. tostring(p))
            if key and not A.seen[key] then A.seen[key] = p added = true end
        end
    end
    if added then A.saveSpots() end
    return A.uniq(A.seen)
end
function A.list()
    local out = {}
    local cap = A.cap()
    local sp = find(workspace, "Game.Jobs.CriminalATMSpawners")
    local now = os.clock()
    for _, d in ipairs(sp and sp:GetDescendants() or {}) do
        if d:IsA("Model") and d.Name:sub(1, 11) == "CriminalATM" and not d.Name:find("Spawner", 1, true) then
            local okp, p = pcall(function() return d:GetPivot().Position end)
            local n = tonumber(d:GetAttribute("ATMNumber"))
            local usable = okp and A.valid(d) and d:GetAttribute("CustomATMTypeId") ~= "Water" and not (cap and n and n > cap)
            if okp then
                if usable then A.known[A.key(p)] = { pos = p, t = now } else A.known[A.key(p)] = nil end
            end
            if usable and (A.skip[d] or 0) < now then out[#out + 1] = d end
        end
    end
    return out
end
function A.dropoff()
    local sp = find(workspace, "Game.Jobs.CriminalDropOffSpawners")
    local out, added = {}, false
    for _, d in ipairs(sp and sp:GetDescendants() or {}) do
        local isPoint = d.Name == "CriminalDropOffPoint" and d:IsA("Model")
        local isSpawner = d.Parent == sp and (d:IsA("BasePart") or d:IsA("Model"))
        if isPoint or isSpawner then
            local ok, p = pcall(function() return d:IsA("BasePart") and d.Position or d:GetPivot().Position end)
            if ok and p then
                local key = math.floor(p.X / 8) .. "," .. math.floor(p.Z / 8)
                if not A.drops[key] then A.drops[key] = p added = true end
            end
            if isPoint then out[#out + 1] = d end
        end
    end
    if added and os.clock() - (A.dropSavedAt or 0) > 10 then
        A.dropSavedAt = os.clock()
        A.saveFile(A.dropFile, A.drops)
    end
    return nearest(out, function(m) return m:GetPivot().Position end)
end
function A.findDrop(alive)
    local drop = A.dropoff()
    if drop then return drop end
    local r = hrp()
    local spots = A.uniq(A.drops)
    if r then table.sort(spots, function(a, b) return (a - r.Position).Magnitude < (b - r.Position).Magnitude end) end
    for i = 1, math.min(#spots, 6) do
        if not alive() then return nil end
        T.stream(spots[i])
        drop = A.dropoff()
        if drop then return drop end
    end
    return nil
end
function A.bagCount()
    local n = 0
    local bp = lp:FindFirstChildOfClass("Backpack")
    for _, t in ipairs(bp and bp:GetChildren() or {}) do if t.Name == "CriminalMoneyBag" then n = n + 1 end end
    for _, t in ipairs(lp.Character and lp.Character:GetChildren() or {}) do if t.Name == "CriminalMoneyBag" then n = n + 1 end end
    return n
end
function A.didBust(atm, crimes0, bags0, wait)
    local t0 = os.clock()
    repeat
        if atm:GetAttribute("State") == "Busted" or num(charAttr("CrimesCommitted")) > crimes0 or A.bagCount() > bags0 then return true end
        task.wait(0.1)
    until os.clock() - t0 >= (wait or 2.5)
    return false
end
function A.mine(atm) return atm:GetAttribute("EngagingPlayerId") == lp.UserId end
function A.standAt(model, alive)
    local pivot = model:GetPivot().Position
    local ring = model:FindFirstChild("Ring") and model.Ring:FindFirstChild("Wall")
    local spot = ring and ring:IsA("BasePart") and ring.Position or pivot
    A.tp(spot, alive)
    if not alive() then return false end
    if not model.Parent then A.lastFail = "ATM unloaded" return false end
    if A.charDist(pivot) > 9 then
        local off = Vector3.new(spot.X - pivot.X, 0, spot.Z - pivot.Z)
        A.tp(pivot + (off.Magnitude > 0.5 and off.Unit * 2 or Vector3.new(2, 0, 0)), alive)
    end
    if A.charDist(pivot) > 9 then A.lastFail = "Couldn't reach it" return false end
    return true
end
function A.bust(atm, alive)
    local crimes0, bags0 = num(charAttr("CrimesCommitted")), A.bagCount()
    local pa = atm:FindFirstChild("PromptAttachment", true)
    local prompt = pa and pa:FindFirstChildOfClass("ProximityPrompt")
    local held = false
    if prompt and prompt.Enabled then
        held = pcall(function() prompt:InputHoldBegin() end)
        local t0 = os.clock()
        while alive() and os.clock() - t0 < 1.2 and not A.mine(atm) do task.wait(0.1) end
        if not A.mine(atm) then
            pcall(function() prompt:InputHoldEnd() end)
            held = false
        end
    end
    if not alive() then
        if held then pcall(function() prompt:InputHoldEnd() end) end
        return false
    end
    if not A.mine(atm) then
        local ok, why = invokeT("AttemptATMBustStart", 8, atm)
        if not ok and not A.mine(atm) then
            A.lastFail = tostring(why or "no reply")
            return false
        end
    end
    local start = num(atm:GetAttribute("BustingStartTimeEpoch"))
    local need = math.max(0.4, A.bustTime() - 2.5 + 0.6)
    setStatus("rob", "Busting ATM  ·  " .. A.stars() .. " stars")
    local t0 = os.clock()
    while alive() and os.clock() - t0 < need + 0.3 do
        if start > 0 and workspace:GetServerTimeNow() - start >= need then break end
        task.wait(0.1)
    end
    if not alive() then
        if held then pcall(function() prompt:InputHoldEnd() end) end
        return false
    end
    if held then
        local hold = math.max(num(prompt.HoldDuration), 0.5) + 0.3
        while alive() and os.clock() - t0 < hold do task.wait(0.1) end
        pcall(function() prompt:InputHoldEnd() end)
        if A.didBust(atm, crimes0, bags0, 1.5) then return true end
    end
    if A.mine(atm) or not held then
        local ok2, why2 = invokeT("AttemptATMBustComplete", 8, atm)
        if ok2 or A.didBust(atm, crimes0, bags0, 1.5) then return true end
        A.lastFail = tostring(why2 or "no reply")
    end
    return false
end
function A.cashOut(alive)
    setStatus("rob", "Cashing out")
    local drop = A.findDrop(alive)
    if not drop then
        A.lastFail = "No drop-off found yet"
        return false
    end
    local p = drop:GetPivot().Position
    A.tp(p, alive)
    if A.charDist(p) > 9 then A.tp(p, alive) end
    local ok = invokeT("AttemptCriminalJobComplete", 8, drop)
    if not ok then
        task.wait(0.5)
        ok = invokeT("AttemptCriminalJobComplete", 8, drop)
    end
    if ok then
        A.cashouts = A.cashouts + 1
        A.busts = 0
        A.lastFail = nil
        A.progressAt = os.clock()
    else
        A.lastFail = "Cash out refused"
    end
    return ok
end
function A.safeSpot()
    local cops = A.copList()
    local best, bd
    for _, p in ipairs(A.spawners()) do
        local m = math.huge
        for _, c in ipairs(cops) do m = math.min(m, (c - p).Magnitude) end
        if not bd or m > bd then best, bd = p, m end
    end
    return best, bd
end
function A.escape(alive)
    A.escapes = (A.escapes or 0) + 1
    local t0 = os.clock()
    while alive() and os.clock() - t0 < 15 do
        if not A.danger() then return end
        if A.stars() >= 5 and A.bagCount() > 0 then
            local drop = A.dropoff()
            local safe = drop ~= nil
            if drop then
                for _, c in ipairs(A.copList()) do
                    if (c - drop:GetPivot().Position).Magnitude < S.fleeDist * 1.3 then safe = false break end
                end
            end
            if safe then
                setStatus("rob", "Police! Cashing out")
                A.cashOut(alive)
                return
            end
        end
        setStatus("rob", "Police! Escaping")
        local spot = A.safeSpot()
        if not spot then
            local r = hrp()
            if not r then return end
            spot = r.Position + Vector3.new(1200, 0, 1200)
        end
        A.tp(spot + Vector3.new(0, 0, 12), alive)
        task.wait(0.4)
    end
end
function A.scan(alive)
    local dropAt = 0
    while alive() do
        local r = hrp()
        if r then
            local spots = A.spawners()
            table.sort(spots, function(a, b) return (a - r.Position).Magnitude < (b - r.Position).Magnitude end)
            for _, p in ipairs(spots) do
                local key = A.key(p)
                if (A.scanned[key] or 0) < os.clock() and (p - r.Position).Magnitude > 250 then
                    A.scanned[key] = os.clock() + 25
                    pcall(function() lp:RequestStreamAroundAsync(p, 2) end)
                    break
                end
            end
            A.list()
            if not A.dropoff() and os.clock() - dropAt > 8 then
                dropAt = os.clock()
                local ds = A.uniq(A.drops)
                if #ds > 0 then pcall(function() lp:RequestStreamAroundAsync(ds[math.random(1, #ds)], 2) end) end
            end
        end
        task.wait(0.3)
    end
end
function A.loaded()
    local out = {}
    local sp = find(workspace, "Game.Jobs.CriminalATMSpawners")
    for _, d in ipairs(sp and sp:GetChildren() or {}) do
        local ok, p = pcall(function() return d:IsA("BasePart") and d.Position or d:GetPivot().Position end)
        if ok and p then out[A.key(p)] = true end
    end
    return out
end
function A.remembered()
    local r = hrp()
    if not r then return nil end
    local loaded = A.loaded()
    local best, bd
    for key, k in pairs(A.known) do
        if os.clock() - k.t > 150 or loaded[key] then
            if os.clock() - k.t > 150 then A.known[key] = nil end
        elseif (A.visited[key] or 0) < os.clock() then
            local d = (k.pos - r.Position).Magnitude
            if not bd or d < bd then best, bd = k.pos, d end
        end
    end
    return best, best and A.key(best)
end
function A.wander(alive)
    local r = hrp()
    if not r then return end
    local target, key = A.remembered()
    if not target then
        local loaded = A.loaded()
        local bd
        for _, p in ipairs(A.spawners()) do
            local k = A.key(p)
            if not loaded[k] and (A.visited[k] or 0) < os.clock() then
                local d = (p - r.Position).Magnitude
                if not bd or d < bd then target, bd, key = p, d, k end
            end
        end
    end
    if not target then
        local bd
        for _, p in ipairs(A.spawners()) do
            local k = A.key(p)
            if (A.visited[k] or 0) < os.clock() then
                local d = (p - r.Position).Magnitude
                if d > 300 and (not bd or d < bd) then target, bd, key = p, d, k end
            end
        end
    end
    if not target then
        A.visited = {}
        setStatus("rob", "Waiting for ATMs to respawn")
        task.wait(1)
        return
    end
    A.visited[key] = os.clock() + 60
    setStatus("rob", "Checking ATM spots")
    A.tp(target + Vector3.new(0, 0, 12), alive)
    local t0 = os.clock()
    while alive() and os.clock() - t0 < 0.8 and not A.pick() do task.wait(0.1) end
end
function A.step(alive)
    local h0 = hum()
    if not (h0 and h0.Health > 0 and hrp()) then setStatus("rob", "Respawning") task.wait(1) return end
    if A.anch then A.unanchor() end
    if h0.PlatformStand and not S.gliding then h0.PlatformStand = false end
    local safe = function() return alive() and not A.danger() end
    if A.danger() then A.escape(alive) return end
    local okJob, why = ensureJob("Criminal")
    if not okJob then setStatus("rob", why) task.wait(3) return end
    if A.stars() == 0 and A.bagCount() == 0 then A.busts = 0 end
    if os.clock() - (A.progressAt or os.clock()) > 120 then
        A.visited, A.scanned, A.skip = {}, {}, setmetatable({}, { __mode = "k" })
        A.progressAt = os.clock()
        A.lastFail = "Restarted search"
    end
    local full = A.stars() >= 5 and A.bagCount() > 0 and math.max(A.busts, A.bagCount()) >= math.max(5, S.robTarget)
    if full and os.clock() > (A.cashRetry or 0) then
        if A.cashOut(safe) then return end
        A.cashRetry = os.clock() + 25
    end
    local atm = A.pick()
    if not atm then
        A.wander(safe)
        return
    end
    setStatus("rob", "Going to ATM  ·  " .. A.stars() .. " stars")
    if not A.standAt(atm, safe) then
        if safe() then A.skip[atm] = os.clock() + 20 end
        return
    end
    local t0 = os.clock()
    while (charAttr("ATMBustDebounce") or charAttr("ArrestDebounce")) and safe() and os.clock() - t0 < 20 do
        setStatus("rob", "Cooldown")
        task.wait(0.15)
    end
    if not safe() or not A.valid(atm) then return end
    if A.bust(atm, safe) then
        A.busts = A.busts + 1
        A.lastFail = nil
        A.progressAt = os.clock()
    elseif safe() then
        A.skip[atm] = os.clock() + 15
    end
end
function A.loop(alive)
    A.visited, A.scanned = {}, {}
    A.skip = setmetatable({}, { __mode = "k" })
    A.lastFail, A.cashRetry = nil, 0
    A.progressAt = os.clock()
    A.unanchor()
    task.spawn(A.scan, alive)
    while alive() do
        local ok, err = pcall(A.step, alive)
        if not ok then
            A.lastFail = tostring(err):sub(1, 60)
            A.unanchor()
            task.wait(1)
        end
        task.wait(0.1)
    end
    A.unanchor()
    setStatus("rob", nil)
end
S.clearAt = function(p)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { lp.Character }
    local hit = workspace:Raycast(p + Vector3.new(0, 40, 0), Vector3.new(0, -90, 0), params)
    if not hit or hit.Material == Enum.Material.Water or hit.Normal.Y < 0.85 then return nil end
    local g = hit.Position
    if workspace:Raycast(g + Vector3.new(0, 2, 0), Vector3.new(0, 25, 0), params) then return nil end
    local op = OverlapParams.new()
    op.FilterType = Enum.RaycastFilterType.Exclude
    op.FilterDescendantsInstances = { lp.Character }
    for _, part in ipairs(workspace:GetPartBoundsInBox(CFrame.new(g + Vector3.new(0, 5, 0)), Vector3.new(16, 8, 26), op)) do
        if part.CanCollide and not part:IsA("Terrain") then return nil end
    end
    return g
end
S.inWater = function()
    local h, r = hum(), hrp()
    if not (h and r) or h.SeatPart then return false end
    if h:GetState() == Enum.HumanoidStateType.Swimming or h.FloorMaterial == Enum.Material.Water then return true end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { lp.Character }
    local hit = workspace:Raycast(r.Position + Vector3.new(0, 2, 0), Vector3.new(0, -30, 0), params)
    return hit ~= nil and hit.Material == Enum.Material.Water
end
S.spotClear = function()
    local r = hrp()
    if not r or S.inWater() then return false end
    local g = S.clearAt(r.Position)
    return g ~= nil and math.abs(g.Y - r.Position.Y) < 8
end
S.toLand = function(level)
    local r = hrp()
    if not r then return end
    local h = hum()
    if h and h.SeatPart then h.Sit = false task.wait(0.2) end
    local here = r.Position
    local maxR = ({ 60, 160, 0 })[level or 1] or 0
    for _, rad in ipairs({ 20, 35, 55, 80, 120, 160 }) do
        if rad > maxR then break end
        for i = 0, 7 do
            local a = i * math.pi / 4
            local g = S.clearAt(here + Vector3.new(math.cos(a) * rad, 0, math.sin(a) * rad))
            if g then
                setStatus(S.owner and ({ de_atm = "rob", de_delivery = "del", de_scenes = "pol", de_arrest = "pol", de_drive = "drive", de_race = "race" })[S.owner] or "drive", "Finding a clear spot to spawn")
                T.go(g + Vector3.new(0, 3, 0), { tol = 4 })
                task.wait(0.3)
                return
            end
        end
    end
    local spots = A.spawners()
    table.sort(spots, function(a, b) return (a - here).Magnitude < (b - here).Magnitude end)
    spots[#spots + 1] = Vector3.new(-320, 18, -1650)
    for i = 1, math.min(#spots, 5) do
        T.stream(spots[i])
        for _, o in ipairs({ Vector3.new(0, 0, 20), Vector3.new(20, 0, 0), Vector3.new(0, 0, -20), Vector3.new(-20, 0, 0), Vector3.new(30, 0, 30), Vector3.new(-30, 0, -30) }) do
            local g = S.clearAt(spots[i] + o)
            if g then
                T.go(g + Vector3.new(0, 3, 0), { tol = 4 })
                task.wait(0.3)
                return
            end
        end
    end
end

local D = { state = nil, done = 0, lastPos = {}, stamp = 0, seen = {} }
onRemote("DeliveryStateChanged", function(s) D.state = s D.stamp = os.clock() end)
onRemote("DeliveryCompleted", function(info)
    D.state = nil
    D.stamp = os.clock()
    if type(info) == "table" then
        if not info.FailureReason then D.done = D.done + 1 end
        D.lastPos = {}
        for _, a in ipairs({ info.PickupAdornee, info.DestinationAdornee }) do
            if typeof(a) == "Instance" and a:IsA("BasePart") then D.lastPos[#D.lastPos + 1] = a.Position end
        end
        D.fail = info.FailureReason
    end
end)
function D.scan()
    local f = find(workspace, "Game.Jobs.Delivery.DeliveryLocations")
    for _, d in ipairs(f and f:GetChildren() or {}) do
        if d:IsA("BasePart") then D.seen[d:GetAttribute("ComponentServerId") or tostring(d.Position)] = d.Position end
    end
end
function D.partAt(pos)
    local f = find(workspace, "Game.Jobs.Delivery.DeliveryLocations")
    for _, d in ipairs(f and f:GetChildren() or {}) do
        if d:IsA("BasePart") and (d.Position - pos).Magnitude < 2 then return d end
    end
    return nil
end
function D.timeLeft(s)
    if type(s) ~= "table" or not s.ExpirationTime then return nil end
    return num(s.ExpirationTime) - workspace:GetServerTimeNow()
end
function D.speedFor(pos, s)
    local root = T.mover()
    local sp = S.speed
    local left = D.timeLeft(s)
    if root and left and left > 0 then
        local dist = (pos - root.Position).Magnitude + S.height * 2
        sp = math.max(sp, dist / math.max(left - 2, 1))
    end
    return math.min(sp, speedCap())
end
function D.tp(pos)
    A.exitCar()
    T.stream(pos)
    local r = hrp()
    if not r then return false end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { lp.Character }
    local hit = workspace:Raycast(pos + Vector3.new(0, 4, 0), Vector3.new(0, -20, 0), params)
    local y = hit and hit.Position.Y or pos.Y
    r.AssemblyLinearVelocity = Vector3.zero
    r.CFrame = CFrame.new(pos.X, y + 3, pos.Z)
    return true
end
function D.arrive(pos, alive, s)
    local before = D.stamp
    D.tp(pos)
    local t0 = os.clock()
    while alive() and D.stamp == before and os.clock() - t0 < 2 do task.wait(0.1) end
    if D.stamp == before then
        local part = D.partAt(pos)
        if part then fire("DeliveryLocationInteracted", part) end
    end
end
D.DJT = safeRequire(find(Mods, "Client.Jobs.Tasks.DeliveryJobTask"))
D.skip = {}
function D.get()
    if D.DJT then
        local ok, s = gcall(D.DJT.GetCurrentDeliveryState)
        if ok and type(s) == "table" then return s end
    end
    return D.state
end
function D.locations()
    D.scan()
    local out = {}
    for _, p in pairs(D.seen) do
        local bad = (D.skip[tostring(p)] or 0) > os.clock()
        for _, q in ipairs(D.lastPos) do if (q - p).Magnitude < 2 then bad = true end end
        if not bad then out[#out + 1] = p end
    end
    return out
end
function D.hold(sec, alive)
    local t0 = os.clock()
    while alive() and os.clock() - t0 < sec do
        local r = T.mover()
        if r then T.push(r, Vector3.zero, 0) end
        RunService.Heartbeat:Wait()
    end
end
function D.step(alive)
    local h0 = hum()
    if not (h0 and h0.Health > 0 and hrp()) then setStatus("del", "Respawning") task.wait(1) return end
    if inCar() then A.exitCar() end
    if hasBag() then
        if A.stars() >= 5 then A.cashOut(alive) else setStatus("del", "Rob to 5 stars to cash out your loot") task.wait(2) end
        return
    end
    local okJob, why = ensureJob("Delivery", S.mode)
    if not okJob then setStatus("del", why) task.wait(3) return end
    local s = D.get()
    local cm = lp.Character and lp.Character:GetAttribute("DeliveryMode")
    if type(s) ~= "table" and cm and cm ~= S.mode and os.clock() - (D.modeAt or 0) > 10 then
        D.modeAt = os.clock()
        fire("SetDeliveryMode", S.mode)
    end
    local carried = type(s) == "table" and num(s.ItemsCarried) or 0
    local maxc = type(s) == "table" and math.max(1, num(s.MaxCapacity)) or 1
    local left = D.timeLeft(s)
    local tl = left and string.format("  ·  %ds", math.max(0, math.floor(left))) or ""
    local emptyPickup = type(s) == "table" and s.PackagesRemainingAtPickup ~= nil and num(s.PackagesRemainingAtPickup) <= 0
    if type(s) ~= "table" then
        setStatus("del", "Finding a pickup")
        local loc = nearest(D.locations(), function(p) return p end)
        if loc then
            D.arrive(loc, alive)
            local t0 = os.clock()
            while alive() and D.get() == nil and os.clock() - t0 < 5 do task.wait(0.2) end
            if D.get() == nil then D.skip[tostring(loc)] = os.clock() + 120 end
        else
            setStatus("del", "Looking for delivery spots")
            local sp = A.spawners()
            for _, p in ipairs(S.policeSpots and S.policeSpots() or {}) do sp[#sp + 1] = p end
            local pick = sp[math.random(1, math.max(1, #sp))] or Vector3.new(-320, 18, -1650)
            D.tp(pick)
            task.wait(1)
        end
    elseif s.IsDropping then
        setStatus("del", "Unloading" .. tl)
        D.hold(0.3, alive)
    elseif carried > 0 and s.DestinationPosition and (carried >= maxc or emptyPickup) then
        setStatus("del", string.format("Delivering %d packages%s", carried, tl))
        D.arrive(s.DestinationPosition, alive, s)
        local t0 = os.clock()
        while alive() and D.get() == s and os.clock() - t0 < 8 do D.hold(0.2, alive) end
    elseif s.IsCollecting then
        setStatus("del", string.format("Loading %d/%d%s", carried, maxc, tl))
        D.hold(0.3, alive)
    elseif s.PickupPosition then
        setStatus("del", "Going to pickup" .. tl)
        D.arrive(s.PickupPosition, alive, s)
        local t0 = os.clock()
        while alive() and D.get() == s and os.clock() - t0 < 4 do D.hold(0.2, alive) end
    else
        task.wait(0.5)
    end
end
function D.loop(alive)
    while alive() do
        local ok, err = pcall(D.step, alive)
        if not ok then D.fail = tostring(err):sub(1, 60) T.stop() task.wait(1) end
        task.wait(0.15)
    end
    setStatus("del", nil)
end


local P = { cleared = 0, arrests = 0 }
onRemote("LocalSecurityArrestCompleted", function() P.arrests = P.arrests + 1 end)
function P.scenes()
    local sp = find(workspace, "Game.Jobs.SecurityCrimeSceneSpawners")
    local out = {}
    for _, d in ipairs(sp and sp:GetDescendants() or {}) do
        if d:IsA("Model") and d.Name:match("^CrimeScene") then
            local e = d:GetAttribute("EngagingPlayerId")
            if d:GetAttribute("State") == "Normal" and (e == nil or e == lp.UserId) and (P.skip and (P.skip[d] or 0) or 0) < os.clock() then out[#out + 1] = d end
        end
    end
    return out
end
P.skip = setmetatable({}, { __mode = "k" })
P.tskip = {}
P.seen = {}
P.visited = {}
P.file = "cw_de_scene_spots.json"
A.loadFile(P.file, P.seen)
function P.spawnerSpots()
    local sp = find(workspace, "Game.Jobs.SecurityCrimeSceneSpawners")
    local added = false
    for _, d in ipairs(sp and sp:GetChildren() or {}) do
        local ok, p = pcall(function() return d:IsA("BasePart") and d.Position or d:GetPivot().Position end)
        local key = ok and p and (d:GetAttribute("ComponentServerId") or d:GetFullName() .. tostring(p))
        if key and not P.seen[key] then P.seen[key] = p added = true end
    end
    if added and os.clock() - (P.savedAt or 0) > 20 then
        P.savedAt = os.clock()
        A.saveFile(P.file, P.seen)
    end
    return A.uniq(P.seen)
end
S.policeSpots = P.spawnerSpots
function P.bagCheck(alive)
    if not hasBag() then return false end
    if A.stars() >= 5 then A.cashOut(alive) else setStatus("pol", "Rob to 5 stars to cash out your loot") task.wait(2) end
    return true
end
function P.wantedWait()
    local w = num(charAttr("CriminalExpireEpoch")) - os.time()
    if w <= 0 then return false end
    setStatus("pol", "Still wanted  ·  " .. math.floor(w) .. "s")
    task.wait(1)
    return true
end
function P.scan(alive)
    P.scanned = P.scanned or {}
    while alive() do
        local r = hrp()
        if r then
            local spots = P.spawnerSpots()
            table.sort(spots, function(a, b) return (a - r.Position).Magnitude < (b - r.Position).Magnitude end)
            for _, p in ipairs(spots) do
                local key = math.floor(p.X / 10) .. "," .. math.floor(p.Z / 10)
                if (P.scanned[key] or 0) < os.clock() and (p - r.Position).Magnitude > 250 then
                    P.scanned[key] = os.clock() + 30
                    pcall(function() lp:RequestStreamAroundAsync(p, 2) end)
                    break
                end
            end
        end
        task.wait(0.3)
    end
end
function P.loaded()
    local out = {}
    local sp = find(workspace, "Game.Jobs.SecurityCrimeSceneSpawners")
    for _, d in ipairs(sp and sp:GetChildren() or {}) do
        local ok, p = pcall(function() return d:IsA("BasePart") and d.Position or d:GetPivot().Position end)
        if ok and p then out[math.floor(p.X / 10) .. "," .. math.floor(p.Z / 10)] = true end
    end
    return out
end
function P.wander(alive)
    local r = hrp()
    if not r then return end
    local loaded = P.loaded()
    local best, bd
    for _, p in ipairs(P.spawnerSpots()) do
        local key = math.floor(p.X / 10) .. "," .. math.floor(p.Z / 10)
        if not loaded[key] and (P.visited[key] or 0) < os.clock() then
            local d = (p - r.Position).Magnitude
            if not bd or d < bd then best, bd = p, d end
        end
    end
    if not best then
        setStatus("pol", "Waiting for crime scenes")
        task.wait(1)
        return
    end
    P.visited[math.floor(best.X / 10) .. "," .. math.floor(best.Z / 10)] = os.clock() + 90
    setStatus("pol", "Checking crime scene spots")
    A.tp(best + Vector3.new(0, 0, 12), alive)
    local t0 = os.clock()
    while alive() and os.clock() - t0 < 0.6 and #P.scenes() == 0 do task.wait(0.1) end
end
function P.useTime()
    local st = statsFolder()
    local pass = st and find(st, "Jobs.HasSecurityPass")
    return 5
end
function P.sceneStep(alive)
    local h0 = hum()
    if not (h0 and h0.Health > 0 and hrp()) then setStatus("pol", "Respawning") task.wait(1) return end
    if P.bagCheck(alive) or P.wantedWait() then return end
    local okJob, why = ensureJob("Security")
    if not okJob then setStatus("pol", why) task.wait(3) return end
    local sc = nearest(P.scenes(), function(m) return m:GetPivot().Position end)
    if not sc then
        P.wander(alive)
        return
    end
    setStatus("pol", "Going to crime scene")
    local sp = sc:GetPivot().Position
    A.tp(sp + Vector3.new(0, 0, 3), alive)
    local t0 = os.clock()
    while alive() and os.clock() - t0 < 0.25 do task.wait() end
    if A.charDist(sp) > 11 then A.tp(sp, alive) task.wait(0.15) end
    if A.charDist(sp) > 11 then
        P.skip[sc] = os.clock() + 30
        P.lastFail = "Couldn't reach the scene"
        return
    end
    t0 = os.clock()
    while charAttr("CrimeSceneUsedDebounce") and alive() and os.clock() - t0 < 20 do
        setStatus("pol", "Cooldown")
        task.wait(0.2)
    end
    if not alive() then return end
    local st = sc:GetAttribute("State")
    local e = sc:GetAttribute("EngagingPlayerId")
    if not sc.Parent or st == "Used" or st == "Disabled" or (e ~= nil and e ~= lp.UserId) then return end
    setStatus("pol", "Clearing crime scene")
    local mine = function() return sc:GetAttribute("EngagingPlayerId") == lp.UserId end
    local used = function() return sc:GetAttribute("State") == "Used" end
    local prompt = sc:FindFirstChildWhichIsA("ProximityPrompt", true)
    local held = false
    if prompt and prompt.Enabled then
        held = pcall(function() prompt:InputHoldBegin() end)
        t0 = os.clock()
        while alive() and os.clock() - t0 < 1.5 and not mine() do task.wait(0.1) end
        if not mine() then pcall(function() prompt:InputHoldEnd() end) held = false end
    end
    if not mine() then
        local ok, why = invokeT("AttemptStartUsingCrimeScene", 8, sc)
        if not ok and not mine() then
            P.skip[sc] = os.clock() + 10
            P.lastFail = tostring(why or "Start refused")
            return
        end
    end
    local start = num(sc:GetAttribute("UsingStartTimeEpoch"))
    local need = math.max(0.5, P.useTime() - 2.5 + 0.6)
    t0 = os.clock()
    local hold = held and (math.max(num(prompt.HoldDuration), 0.5) + 0.3) or 0
    while alive() and not used() and os.clock() - t0 < math.max(need + 0.5, hold) do
        if not held and start > 0 and workspace:GetServerTimeNow() - start >= need then break end
        task.wait(0.1)
    end
    if held then pcall(function() prompt:InputHoldEnd() end) end
    if not alive() then return end
    local w0 = os.clock()
    while held and not used() and os.clock() - w0 < 1.5 do task.wait(0.1) end
    if used() then
        P.cleared = P.cleared + 1
        P.lastFail = nil
        return
    end
    if A.charDist(sp) > 11 then A.tp(sp, alive) end
    local ok2, why2 = invokeT("AttemptFinishUsingCrimeScene", 8, sc)
    if not ok2 and not used() then
        task.wait(0.5)
        ok2, why2 = invokeT("AttemptFinishUsingCrimeScene", 8, sc)
    end
    if ok2 or used() then
        P.cleared = P.cleared + 1
        P.lastFail = nil
    else
        P.skip[sc] = os.clock() + 10
        P.lastFail = tostring(why2 or "Finish refused")
    end
end
function P.sceneLoop(alive)
    task.spawn(P.scan, alive)
    while alive() do
        local ok, err = pcall(P.sceneStep, alive)
        if not ok then P.lastFail = tostring(err):sub(1, 60) task.wait(1) end
        task.wait(0.1)
    end
    setStatus("pol", nil)
end
function P.targets()
    local out = {}
    local now = os.time()
    for _, p in ipairs(Players:GetPlayers()) do
        local c = p.Character
        if p ~= lp and c and p:GetAttribute("JobId") == "Criminal" and num(c:GetAttribute("CriminalExpireEpoch")) > now
            and not c:GetAttribute("ArrestDebounce") and c:FindFirstChild("HumanoidRootPart") and (P.tskip[p.UserId] or 0) < os.clock()
            and num(c:GetAttribute("CooldownCharacterFinishEpoch")) <= now and num(c:GetAttribute("CooldownVehicleFinishEpoch")) <= now then
            out[#out + 1] = p
        end
    end
    return out
end
function P.arrestStep(alive)
    if not ensureCar(true) then noCar("pol") return end
    if P.bagCheck(alive) or P.wantedWait() then return end
    local okJob, why = ensureJob("Security")
    if not okJob then setStatus("pol", why) task.wait(3) return end
    local tgt = nearest(P.targets(), function(p) return p.Character.HumanoidRootPart.Position end)
    if not tgt then
        setStatus("pol", "No wanted outlaws")
        task.wait(2)
        return
    end
    setStatus("pol", "Chasing " .. tgt.DisplayName)
    local t0 = os.clock()
    local function still()
        local c = tgt.Character
        return alive() and c and c.Parent and num(c:GetAttribute("CriminalExpireEpoch")) > os.time() and os.clock() - t0 < 25
    end
    S.chasing = true
    S.gliding = true
    while still() do
        local tr = tgt.Character and tgt.Character:FindFirstChild("HumanoidRootPart")
        local root, model = T.mover()
        if not (tr and root) then break end
        local tv = tr.AssemblyLinearVelocity
        local back = tgt.Character:GetAttribute("InHeist") and 3 or 8
        local goal = tr.Position + tv * 0.15 + Vector3.new(0, 2, 0)
        local d = goal - root.Position
        if d.Magnitude > 120 then
            T.go(goal, { alive = still, tol = 15, ground = true })
            S.gliding = true
        else
            if d.Magnitude > back then
                local sp = math.clamp(d.Magnitude * 4, tv.Magnitude, math.min(S.speed, speedCap()))
                T.push(root, d.Unit, sp)
                pcall(T.face, model, root, d.Unit)
            else
                T.push(root, tv.Magnitude > 1 and tv.Unit or Vector3.zero, tv.Magnitude)
            end
            RunService.Heartbeat:Wait()
        end
    end
    S.chasing = false
    T.stop()
    if tgt.Character and num(tgt.Character:GetAttribute("CriminalExpireEpoch")) > os.time() then P.tskip[tgt.UserId] = os.clock() + 45 end
end
function P.arrestLoop(alive)
    while alive() do
        local ok, err = pcall(P.arrestStep, alive)
        if not ok then P.lastFail = tostring(err):sub(1, 60) S.chasing = false T.stop() task.wait(1) end
        task.wait(0.2)
    end
    setStatus("pol", nil)
end


local DR = { miles = 0, laps = 0, recovers = 0, mode = "Legit", mph = 300, turn = "U-Turn", inset = 450,
    A = Vector3.new(-18249.7, 35.1, -676.0), B = Vector3.new(-34551.8, 34.0, -32828.1),
    speeds = {}, names = {}, bad = {}, list = {}, byLabel = {} }
DR.axis = Vector3.new(DR.B.X - DR.A.X, 0, DR.B.Z - DR.A.Z)
DR.len = DR.axis.Magnitude
DR.axis = DR.axis.Unit
DR.tA, DR.tB = DR.inset, DR.len - DR.inset
function DR.at(t)
    return DR.A + (DR.B - DR.A) * math.clamp(t / DR.len, 0, 1)
end
function DR.proj(pos)
    local rel = Vector3.new(pos.X - DR.A.X, 0, pos.Z - DR.A.Z)
    local t = rel:Dot(DR.axis)
    return t, rel - DR.axis * t
end
function DR.right(fwd) return Vector3.new(-fwd.Z, 0, fwd.X) end
function DR.params(car)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local ex = { lp.Character }
    if car then ex[#ex + 1] = car end
    local vf = workspace:FindFirstChild("Vehicles")
    if vf then ex[#ex + 1] = vf end
    params.FilterDescendantsInstances = ex
    return params
end
function DR.ground(pos, car)
    local hit = workspace:Raycast(pos + Vector3.new(0, 4, 0), Vector3.new(0, -60, 0), DR.params(car))
    return hit and hit.Position.Y or nil
end
function DR.lane(pos, fwd, refY, car)
    local right = DR.right(fwd)
    local params = DR.params(car)
    local runs, start, step, n = {}, nil, 3.5, 12
    for i = -n, n do
        local o = i * step
        local hit = workspace:Raycast(Vector3.new(pos.X, refY + 6, pos.Z) + right * o, Vector3.new(0, -14, 0), params)
        local road = hit and math.abs(hit.Position.Y - refY) < 1.6 and hit.Material ~= Enum.Material.Water
        if road then start = start or o
        elseif start then runs[#runs + 1] = { start, o - step } start = nil end
    end
    if start then runs[#runs + 1] = { start, n * step } end
    local pick, pd
    for _, r in ipairs(runs) do
        if r[2] - r[1] >= 10 then
            local d = (r[1] <= 0 and r[2] >= 0) and 0 or math.min(math.abs(r[1]), math.abs(r[2]))
            if not pd or d < pd then pick, pd = r, d end
        end
    end
    if not pick then return nil end
    return (pick[1] + pick[2]) / 2, pick[2] - pick[1]
end
function DR.stock()
    local okc, c = gcall(M.VC and M.VC.getActiveChassisController)
    if not (okc and type(c) == "table") then return nil end
    local ok, top = pcall(function()
        local tune = S.origTune and S.origTune(c) or c.Tune
        local ts = tune.TransmissionSpeeds
        local em = num(c.PerformanceUpgrades and c.PerformanceUpgrades.EngineMult)
        return num(ts[#ts]) * (em > 0 and em or 1) * 0.77 * 2 + 2
    end)
    return ok and top > 10 and top or nil
end
function DR.speed()
    if DR.mode == "Boosted" then return math.min(DR.mph / MPH, speedCap()) end
    local st = DR.stock()
    return math.min(st and st * 0.95 or 120 / MPH, speedCap())
end
function DR.roots(car)
    local seen, list = {}, {}
    for _, d in ipairs(car:GetDescendants()) do
        if d:IsA("BasePart") and not d.Anchored then
            local r = d.AssemblyRootPart
            if r and not seen[r] then seen[r] = true list[#list + 1] = r end
        end
    end
    return list
end
function DR.place(model, root, pos, fwd)
    local off = root.CFrame:ToObjectSpace(model:GetPivot())
    model:PivotTo(CFrame.lookAt(pos, pos + fwd) * off)
    for _, r in ipairs(DR.roots(model)) do
        r.AssemblyLinearVelocity = Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
    end
end
function DR.level(model, root, fwd, lift)
    local p = root.Position + Vector3.new(0, lift or 0, 0)
    local off = root.CFrame:ToObjectSpace(model:GetPivot())
    model:PivotTo(CFrame.lookAt(p, p + fwd) * off)
    for _, r in ipairs(DR.roots(model)) do r.AssemblyAngularVelocity = Vector3.zero end
end
function DR.setVel(roots, root, want, damp)
    local v = root.AssemblyLinearVelocity
    local delta = Vector3.new(want.X - v.X, 0, want.Z - v.Z)
    if want.Y < v.Y then delta = delta + Vector3.new(0, want.Y - v.Y, 0) end
    for _, r in ipairs(roots) do
        if r.Parent then r.AssemblyLinearVelocity = r.AssemblyLinearVelocity + delta end
    end
    local cf = root.CFrame
    local av = cf:VectorToObjectSpace(root.AssemblyAngularVelocity)
    local k = damp or 0.5
    root.AssemblyAngularVelocity = cf:VectorToWorldSpace(Vector3.new(av.X * k, av.Y * 0.5, av.Z * k))
end
function DR.spot(t, fwd, car)
    local p = DR.at(t)
    local params, right, low = DR.params(car), DR.right(fwd), nil
    for i = -12, 12 do
        local hit = workspace:Raycast(p + right * (i * 3.5) + Vector3.new(0, 15, 0), Vector3.new(0, -35, 0), params)
        if hit and hit.Material ~= Enum.Material.Water and (not low or hit.Position.Y < low) then low = hit.Position.Y end
    end
    local shift = low and DR.lane(p, fwd, low, car)
    if shift then p = p + right * shift end
    local gy = DR.ground(p + Vector3.new(0, 20, 0), car) or low or p.Y
    return Vector3.new(p.X, gy + 3, p.Z)
end
function DR.near(pos, within)
    local root = T.mover()
    return root ~= nil and (Vector3.new(pos.X, 0, pos.Z) - Vector3.new(root.Position.X, 0, root.Position.Z)).Magnitude <= within
end
function DR.glide(pos, fwd, alive)
    local bestD, bestT = math.huge, os.clock()
    while alive() and RUNNING do
        RunService.Heartbeat:Wait()
        local root, model = T.mover()
        if not root then return false end
        local d = pos + Vector3.new(0, 4, 0) - root.Position
        local dist = d.Magnitude
        if dist < 10 then break end
        if dist < bestD - 1 then bestD, bestT = dist, os.clock() elseif os.clock() - bestT > 3 then return false end
        local sp = math.min(900, speedCap(), math.max(dist * 4, 20))
        local v = d.Unit * sp
        for _, r in ipairs(DR.roots(model)) do
            r.AssemblyLinearVelocity = v
            r.AssemblyAngularVelocity = Vector3.zero
        end
        pcall(T.face, model, root, d)
    end
    T.stop()
    local root, model = T.mover()
    if root then pcall(DR.level, model, root, fwd, 0) end
    return DR.near(pos, 40)
end
function DR.teleport(t, sign, alive)
    alive = alive or function() return RUNNING end
    t = math.clamp(t, DR.tA, DR.tB)
    local fwd = DR.axis * sign
    local pos = DR.at(t) + Vector3.new(0, 3, 0)
    for try = 1, 3 do
        if not alive() then return false end
        if try > 1 then
            T.stream(DR.at(t))
            pos = DR.spot(t, fwd, myCar())
        end
        local root, model = T.mover()
        if not (root and model) then return false end
        setStatus("drive", "Teleporting to the highway")
        authorize()
        if inCar() then
            DR.place(model, root, pos, fwd)
        else
            root.AssemblyLinearVelocity = Vector3.zero
            root.CFrame = CFrame.lookAt(pos + Vector3.new(0, 2, 0), pos + Vector3.new(0, 2, 0) + fwd)
        end
        local done = false
        task.spawn(function() T.stream(DR.at(t)) done = true end)
        local t0 = os.clock()
        while alive() and os.clock() - t0 < 3 and (not done or os.clock() - t0 < 0.6) do
            RunService.Heartbeat:Wait()
            local _, m = T.mover()
            for _, r in ipairs(m and DR.roots(m) or {}) do
                r.AssemblyLinearVelocity = Vector3.zero
                r.AssemblyAngularVelocity = Vector3.zero
            end
        end
        if DR.near(pos, 60) then
            local fix = DR.spot(t, fwd, myCar())
            local r2, m2 = T.mover()
            if r2 and inCar() and (fix - r2.Position).Magnitude > 4 then
                authorize()
                DR.place(m2, r2, fix, fwd)
            end
            return true
        end
    end
    setStatus("drive", "Teleport blocked, driving there")
    DR.lastFail = "Teleport got reverted"
    T.stream(DR.at(t))
    return DR.glide(DR.spot(t, fwd, myCar()), fwd, alive)
end
function DR.reach(alive)
    local root = T.mover()
    if not root then return nil end
    local t, lat = DR.proj(root.Position)
    if lat.Magnitude < 90 and t > DR.tA - 80 and t < DR.tB + 80 and math.abs(root.Position.Y - DR.at(t).Y) < 25 then
        t = math.clamp(t, DR.tA, DR.tB)
        return (DR.tB - t > t - DR.tA) and 1 or -1
    end
    local useA = (DR.at(DR.tA) - root.Position).Magnitude <= (DR.at(DR.tB) - root.Position).Magnitude
    local sign = useA and 1 or -1
    if not DR.teleport(useA and DR.tA or DR.tB, sign, alive) then
        DR.lastFail = DR.lastFail or "Couldn't reach the highway"
        return nil
    end
    return sign
end
function DR.turnAround(alive, sign, roots, side)
    local fwd = DR.axis * sign
    local t0 = os.clock()
    setStatus("drive", "Turning around")
    while alive() and os.clock() - t0 < 0.7 do
        RunService.Heartbeat:Wait()
        local root = T.mover()
        if not root then return end
        DR.setVel(roots, root, Vector3.zero)
    end
    local root, model = T.mover()
    if not root then return end
    if DR.turn == "Quick Flip" then
        DR.level(model, root, -fwd, 0.5)
        return
    end
    local sp, rad, ang = 22, 7, 0
    local dirSign = (side or 1) >= 0 and -1 or 1
    while alive() and inCar() and ang < math.pi do
        local dt = RunService.Heartbeat:Wait()
        root, model = T.mover()
        if not root then return end
        ang = math.min(math.pi, ang + sp / rad * dt)
        local head = CFrame.Angles(0, ang * dirSign, 0):VectorToWorldSpace(fwd)
        DR.setVel(roots, root, head * sp)
        pcall(T.face, model, root, head)
    end
    root, model = T.mover()
    if root then pcall(DR.level, model, root, -fwd, 0) end
end
function DR.top(id) return 0 end
function DR.name(id)
    if DR.names[id] then return DR.names[id] end
    local n = tostring(id):gsub("[%-_]", " ")
    DR.names[id] = n
    return n
end
function DR.scanCars()
    local list = {}
    for _, id in ipairs(ownedCars()) do
        if landCar(id) then list[#list + 1] = { id = id, mph = DR.top(id), name = DR.name(id) } end
    end
    table.sort(list, function(a, b) return a.name:lower() < b.name:lower() end)
    DR.list = list
    local labels, byLabel = {}, {}
    for _, c in ipairs(list) do
        local lab = c.mph > 0 and string.format("%s  ·  %d mph", c.name, math.floor(c.mph)) or c.name
        if byLabel[lab] then lab = lab .. "  (" .. c.id .. ")" end
        labels[#labels + 1] = lab
        byLabel[lab] = c.id
    end
    if #labels == 0 then labels = { "No cars found" } end
    DR.byLabel = byLabel
    return labels
end
function DR.labelOf(id)
    for lab, v in pairs(DR.byLabel) do if v == id then return lab end end
    return nil
end
function DR.want()
    if DR.pick and (DR.bad[DR.pick] or 0) < os.clock() then return DR.pick end
    for _, c in ipairs(DR.list) do
        if (DR.bad[c.id] or 0) < os.clock() and not S.isFree(c.id) then return c.id end
    end
    for _, c in ipairs(DR.list) do
        if (DR.bad[c.id] or 0) < os.clock() then return c.id end
    end
    return S.spawnId
end
function DR.ensure()
    local want = DR.want()
    local car = myCar()
    if car and want then
        local cv = car:FindFirstChild("CarType")
        local cur = (DR.cur and DR.cur.car == car) and DR.cur.id or (cv and cv.Value)
        if cur and cur ~= want then
            setStatus("drive", "Switching to " .. DR.name(want))
            fire("VehicleEvent", "Despawn")
            local t0 = os.clock()
            while myCar() and os.clock() - t0 < 5 do task.wait(0.2) end
            if myCar() then S.carWhy = "Couldn't swap car" return false end
        end
    end
    local had = myCar()
    S.spawnOverride = want
    local ok = ensureCar(true)
    S.spawnOverride = nil
    if ok and not had and want then DR.cur = { car = myCar(), id = want } end
    if not ok and want and not myCar() and S.carWhy == "Spawn failed, retrying soon" then
        DR.bad[want] = os.clock() + 60
        S.spawnBackoff = 0
    end
    return ok
end
track(lp.CharacterAdded:Connect(function() DR.spawnedAt = os.clock() end))
function DR.run(alive)
    local h, r = hum(), hrp()
    if not (h and r and h.Health > 0) or os.clock() - (DR.spawnedAt or 0) < 2.5 then
        setStatus("drive", "Waiting for character")
        task.wait(0.5)
        return
    end
    DR.swap = false
    if not DR.ensure() then noCar("drive") return end
    local sign = DR.reach(alive)
    if not sign then task.wait(1) return end
    S.driving = true
    DR.lastFail = nil
    local root, model = T.mover()
    local car = myCar()
    if not (root and car) then S.driving = false return end
    local cv = car:FindFirstChild("CarType")
    local carName = DR.name((DR.cur and DR.cur.car == car and DR.cur.id) or (cv and cv.Value) or "Car")
    local roots, rootsAt = DR.roots(car), os.clock()
    local last, slowAt, streamAt, laneAt = root.Position, nil, 0, 0
    local laneTarget, laneShift = nil, 0
    local stuck, goodAt = 0, os.clock()
    while alive() and inCar() and myCar() == car and not DR.swap do
        RunService.Heartbeat:Wait()
        root, model = T.mover()
        if not root then break end
        if os.clock() - rootsAt > 1 then roots, rootsAt = DR.roots(car), os.clock() end
        local pos = root.Position
        local t = DR.proj(pos)
        local fwd = DR.axis * sign
        local right = DR.right(fwd)
        local left = sign > 0 and (DR.tB - t) or (t - DR.tA)
        local gy = DR.ground(pos, car)
        if left <= 0 then
            DR.turnAround(alive, sign, roots, laneShift)
            sign = -sign
            DR.laps = DR.laps + 0.5
            slowAt, laneTarget = nil, nil
            local r2 = T.mover()
            last = r2 and r2.Position or pos
        else
            if os.clock() - laneAt > 0.2 and gy then
                laneAt = os.clock()
                local shift = DR.lane(pos, fwd, gy, car)
                if shift then laneTarget, laneShift = pos + right * shift, shift end
            end
            if os.clock() - streamAt > 0.7 then
                streamAt = os.clock()
                task.spawn(T.stream, pos + fwd * math.max(700, root.AssemblyLinearVelocity.Magnitude * 3))
            end
            local sp = DR.speed()
            S.driveBoost = DR.mode == "Boosted" and sp or nil
            if left < 300 then sp = math.max(math.min(sp, 60), sp * (left / 300)) end
            local corr = Vector3.zero
            if laneTarget then
                local off = (laneTarget - pos):Dot(right)
                corr = right * math.clamp(off * 1.5, -20, 20)
            end
            local vy = root.AssemblyLinearVelocity.Y
            if gy and pos.Y - gy > 6 then vy = math.min(vy, -40) end
            if root.CFrame.UpVector.Y < 0.5 then
                if os.clock() - (DR.flipAt or 0) > 1 then
                    DR.flipAt = os.clock()
                    pcall(DR.level, model, root, fwd, 2)
                    DR.recovers = DR.recovers + 1
                end
            else
                DR.setVel(roots, root, fwd * sp + corr + Vector3.new(0, vy, 0), DR.mode == "Boosted" and 0.3 or 0.5)
                local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
                if look.Magnitude > 0.1 and look.Unit:Dot(fwd) < 0.9995 then pcall(T.face, model, root, fwd) end
            end
            local along = root.AssemblyLinearVelocity:Dot(fwd)
            if along < sp * 0.3 then
                goodAt = os.clock()
                slowAt = slowAt or os.clock()
                if os.clock() - slowAt > 2.5 then
                    DR.recovers = DR.recovers + 1
                    slowAt = nil
                    stuck = stuck + 1
                    if stuck >= 3 then
                        stuck = 0
                        setStatus("drive", "Stuck, skipping ahead")
                        DR.teleport(t + sign * 150, sign, alive)
                        laneTarget = nil
                        local r2 = T.mover()
                        last = r2 and r2.Position or pos
                    else
                        pcall(DR.level, model, root, fwd, 2)
                    end
                end
            else
                slowAt = nil
                if os.clock() - goodAt > 4 then stuck = 0 end
            end
            local stepLen = (pos - last).Magnitude
            if stepLen < 200 then DR.miles = DR.miles + stepLen * 0.0001551590380139643 end
            last = pos
            setStatus("drive", string.format("%s  ·  %d mph  ·  %.1fk to turn\nLaps %d  ·  %.1f mi  ·  %s%s", sign > 0 and "Outbound" or "Return", math.floor(math.max(along, 0) * MPH), left / 1000, math.floor(DR.laps), DR.miles, carName, DR.recovers > 0 and ("  ·  Recovered " .. DR.recovers) or ""))
        end
    end
    S.driving = false
    S.driveBoost = nil
end
function DR.loop(alive)
    while alive() do
        local ok, err = pcall(DR.run, alive)
        S.driving = false
        S.driveBoost = nil
        if not ok then DR.lastFail = tostring(err):sub(1, 60) T.stop() task.wait(1) end
        task.wait(0.2)
    end
    S.driving = false
    S.driveBoost = nil
    T.stop()
    setStatus("drive", nil)
end

local RC = { state = nil, uuid = nil, runs = 0, finished = false, RU = safeRequire(find(Mods, "Shared.Races.RaceUtil")), RRC = safeRequire(find(Mods, "Shared.Races.RaceRemoteConfig")) }
