    for k in pairs(type(races) == "table" and races or {}) do if type(k) == "string" then out[#out + 1] = k end end
    if #out == 0 then out = { "Circuit", "CrossCountry", "Drag", "Highway", "SofiaBay", "Drawbridge" } end
