    if ok and type(ti) == "table" then
        return (num(ti.MinTimeSeconds) > 0 and num(ti.MinTimeSeconds) or 60), math.max(1, num(ti.MaxLaps))
    end
    local db = type(M.RaceDB) == "table" and type(M.RaceDB.races) == "table" and M.RaceDB.races[track]
