function RC.ground(pos, car)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = { workspace.Terrain }
    local hit = workspace:Raycast(pos + Vector3.new(0, 60, 0), Vector3.new(0, -200, 0), params)
    return hit and hit.Position.Y or nil
end
function RC.follow(cps, finishPart, laps, speed, alive, track)
    local total = #cps * laps + (finishPart and 1 or 0)
    local myIdx = 1
    local lastKey, lastChange = nil, os.clock()
    while alive() do
        local root, model = T.mover()
        if not root then return false end
        local cp, lap, done = RC.progress()
        if done then return true end
        local target, idx
        if cp then
            if cp == #cps and lap >= laps then
                target, idx = finishPart, total
            else
                local nxt = cp % #cps + 1
                target, idx = cps[nxt], math.max(0, lap - (cp == #cps and 0 or 1)) * #cps + nxt
                if lap == 0 then idx = nxt end
            end
        else
            local seq = math.min(myIdx, total)
            if finishPart and seq == total then target = finishPart else target = cps[(seq - 1) % #cps + 1] end
            idx = seq
        end
        if not target then return false end
        local key = tostring(cp) .. ":" .. tostring(lap) .. ":" .. myIdx
        setStatus("race", string.format("Racing %s  ·  %d/%d", track, math.min(idx, total), total))
        local aim = target.Position
        local d = aim - root.Position
        if key ~= lastKey then
            lastKey, lastChange, RC.bestD = key, os.clock(), d.Magnitude
        elseif d.Magnitude < (RC.bestD or math.huge) - 3 then
            RC.bestD, lastChange = d.Magnitude, os.clock()
        end
        if not cp and d.Magnitude < 14 then myIdx = myIdx + 1 end
        if os.clock() - lastChange > 4 then
            local car = myCar()
            if car then
                authorize()
                local off = root.CFrame:ToObjectSpace(car:GetPivot())
                local back = Vector3.new(d.X, 0, d.Z)
                back = back.Magnitude > 1 and back.Unit or Vector3.new(0, 0, 1)
                local from = aim - back * 25
                local gy = RC.ground(from, car)
                if gy and from.Y < gy + 4 then from = Vector3.new(from.X, gy + 4, from.Z) end
                car:PivotTo(CFrame.lookAt(from, from + back) * off)
            end
            lastChange = os.clock()
        end
        RunService.Heartbeat:Wait()
        local vel = (d.Magnitude > 0.1 and d.Unit or Vector3.zero) * speed
        local gy = RC.ground(root.Position, myCar())
        if gy and root.Position.Y < gy + 3 then
            vel = Vector3.new(vel.X, math.max(vel.Y, (gy + 3 - root.Position.Y) * 12), vel.Z)
        end
        root.AssemblyLinearVelocity = vel
        root.AssemblyAngularVelocity = Vector3.zero
        pcall(T.face, model, root, d.Magnitude > 0.1 and d.Unit or Vector3.new(0, 0, 1))
    end
    return false
end
function RC.loop(alive)
    while alive() do
        local okRun, errRun = pcall(function()
        if not ensureCar(true) then noCar("race")
        else
            local track = S.raceTrack
            RC.state, RC.finished = nil, false
            setStatus("race", "Starting " .. track)
            fire("RaceStartTimeTrial", track, "NoOne")
