                if finishPart then path[#path + 1] = RC.aim(finishPart) end
                local root = T.mover()
                local len, prev = 0, root and root.Position or path[1]
                for _, p in ipairs(path) do len = len + (p - prev).Magnitude prev = p end
                local sp = math.clamp(len / (minT * S.racePace), 30, speedCap())
                local racing = function() return alive() and RC.state == "Racing" end
                S.gliding = true
                authorize()
                S.racing = true
                RC.follow(cps, finishPart, laps, sp, racing, track)
                S.racing = false
                T.stop()
                local t1 = os.clock()
                while alive() and RC.state == "Racing" and not RC.finished and os.clock() - t1 < 10 do task.wait(0.2) end
                if RC.finished then
                    RC.runs = RC.runs + 1
                    setStatus("race", "Finished " .. track)
                else
                    setStatus("race", "Race didn't count, retrying")
                end
                task.wait(4)
            end
        end
        end)
        if not okRun then
            RC.lastFail = tostring(errRun):sub(1, 60)
            S.racing = false
            T.stop()
            task.wait(1)
        end
        task.wait(0.5)
    end
    setStatus("race", nil)
end

