        end
    end)
end))

function V.inputs(c)
    if V.input and type(V.input.Get) == "function" then
        local co = coroutine.create(function() return pcall(V.input.Get) end)
        local r = table.pack(coroutine.resume(co))
        if r[1] and r[2] and type(r[3]) == "number" then return r[3], num(r[4]) end
    end
