end
V.asm = setmetatable({}, { __mode = "k" })
function V.assemblies(car)
    local rec = V.asm[car]
    if rec and os.clock() - rec.t < 1 then return rec.list end
    local seen, list = {}, {}
    for _, d in ipairs(car:GetDescendants()) do
        if d:IsA("BasePart") and not d.Anchored then
            local r = d.AssemblyRootPart
            if r and not seen[r] then seen[r] = true list[#list + 1] = r end
        end
    end
    V.asm[car] = { t = os.clock(), list = list }
    return list
end
function V.topOf(tune, c)
    local ts = type(tune) == "table" and tune.TransmissionSpeeds
    local top = type(ts) == "table" and num(ts[#ts]) or 0
    local em = type(c.PerformanceUpgrades) == "table" and num(c.PerformanceUpgrades.EngineMult) or 1
    if em <= 0 then em = 1 end
    return top * em * 0.77 * 2 + 2
end
V.tunes = setmetatable({}, { __mode = "k" })
S.origTune = function(c) local r = V.tunes[c] return r and r.orig or c.Tune end
function V.applyTune(c)
    local rec = V.tunes[c]
    if rec and c.Tune ~= rec.mod and c.Tune ~= rec.orig then rec = nil V.tunes[c] = nil end
    local want = S.driveBoost or ((S.customSpeed and not S.gliding) and S.topMph / MPH or nil)
    if want then
        local orig = rec and rec.orig or c.Tune
        if type(orig) ~= "table" or type(orig.TransmissionSpeeds) ~= "table" then return end
        local stock = V.topOf(orig, c)
        if stock <= 2 then return end
        local k = math.max(1, want / stock * 1.05)
        k = math.floor(k * 20 + 0.5) / 20
        if rec and rec.k == k and c.Tune == rec.mod then return end
        local mod = {}
        for key, val in pairs(orig) do mod[key] = val end
        local ts = {}
        for i, s in ipairs(orig.TransmissionSpeeds) do ts[i] = s * k end
        mod.TransmissionSpeeds = ts
        c.Tune = mod
        V.tunes[c] = { orig = orig, mod = mod, k = k, stock = stock }
    elseif rec then
        if c.Tune == rec.mod then c.Tune = rec.orig end
        V.tunes[c] = nil
    end
end
onClean(function()
    for c, rec in pairs(V.tunes) do pcall(function() if c.Tune == rec.mod then c.Tune = rec.orig end end) end
end)

