local RW = { codes = { "RAMBO", "UWU", "200KMEMBERS", "AIRDROP", "2MLIKES" } }
function RW.playtime()
    if not M.PlayReward then return 0 end
    local ok, list = ycall(M.PlayReward.getUnclaimedRewards, lp)
    local n = 0
    if ok and type(list) == "table" then
        for i in pairs(list) do fire("PlayRewards", i, false) n = n + 1 task.wait(0.3) end
    end
    return n
end
function RW.quests()
    if not M.Quest then return 0 end
    local ok, qs = ycall(M.Quest.getQuestsForLocalPlayer)
    local n = 0
    if ok and type(qs) == "table" then
        for _, q in pairs(qs) do
            if type(q) == "table" and q.QuestId and not q.IsClaimed then
                local okc, done = ycall(M.Quest.hasCompletedQuest, q.QuestId)
                if okc and done then fire("QuestClaimed", q.QuestId, false) n = n + 1 task.wait(0.3) end
            end
        end
    end
    return n
end
function RW.all()
    local n = RW.playtime() + RW.quests()
    fire("ClaimRewards")
    fire("RaceLeaderboardClaimRewards")
    if invoke("IncentivesClaimReward") then n = n + 1 end
    return n
end

local ESP = { objs = {} }
function ESP.mark(key, adornee, color, text, withHl)
    local o = ESP.objs[key]
    if o and o.adornee == adornee and o.bb.Parent then
        o.lbl.Text = text
        if withHl and not o.hl then
            o.hl = Instance.new("Highlight")
            o.hl.FillColor, o.hl.OutlineColor, o.hl.FillTransparency = color, color, 0.6
            o.hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            o.hl.Adornee = adornee
            o.hl.Parent = adornee
        elseif not withHl and o.hl then
            o.hl:Destroy()
            o.hl = nil
        end
        o.seen = true
        return
    end
    if o then pcall(function() if o.hl then o.hl:Destroy() end o.bb:Destroy() end) end
    local bb = Instance.new("BillboardGui")
    bb.Size = UDim2.fromOffset(160, 30)
    bb.AlwaysOnTop = true
    bb.StudsOffset = Vector3.new(0, 6, 0)
    bb.Adornee = adornee
    local lbl = Instance.new("TextLabel")
    lbl.BackgroundTransparency = 1
    lbl.Size = UDim2.fromScale(1, 1)
    lbl.TextColor3 = color
    lbl.TextStrokeTransparency = 0.4
    lbl.Font = Enum.Font.GothamBold
    lbl.TextScaled = true
    lbl.Text = text
    lbl.Parent = bb
    bb.Parent = adornee
    ESP.objs[key] = { bb = bb, lbl = lbl, adornee = adornee, seen = true }
    if withHl then ESP.mark(key, adornee, color, text, true) end
end
function ESP.sweep()
    for k, o in pairs(ESP.objs) do
        if not o.seen then pcall(function() if o.hl then o.hl:Destroy() end o.bb:Destroy() end) ESP.objs[k] = nil else o.seen = false end
    end
end
onClean(function() for _, o in pairs(ESP.objs) do pcall(function() if o.hl then o.hl:Destroy() end o.bb:Destroy() end) end end)
