local LAG = { on = false, conn = nil }
function LAG.one(d)
    if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") or d:IsA("Smoke") or d:IsA("Fire") or d:IsA("Sparkles") then
        d.Enabled = false
    elseif d:IsA("Decal") or d:IsA("Texture") then
        d.Transparency = 1
    elseif d:IsA("BasePart") then
        if d.Material ~= Enum.Material.SmoothPlastic then d.Material = Enum.Material.SmoothPlastic end
        d.Reflectance = 0
        d.CastShadow = false
    elseif d:IsA("PostEffect") then
        d.Enabled = false
    end
end
function LAG.apply()
    local Lighting = game:GetService("Lighting")
    pcall(function()
        Lighting.GlobalShadows = false
        Lighting.FogEnd = 1e9
        for _, e in ipairs(Lighting:GetDescendants()) do
            if e:IsA("PostEffect") then e.Enabled = false end
            if e:IsA("Atmosphere") then e.Density = 0 e.Haze = 0 e.Glare = 0 end
        end
    end)
    pcall(function()
        local t = workspace.Terrain
        t.WaterWaveSize, t.WaterWaveSpeed, t.WaterReflectance = 0, 0, 0
        t.Decoration = false
    end)
    pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
    if not LAG.conn then
        LAG.conn = track(workspace.DescendantAdded:Connect(function(d)
            if LAG.on then pcall(LAG.one, d) end
        end))
    end
    task.spawn(function()
        local list = workspace:GetDescendants()
        for i, d in ipairs(list) do
            if not (LAG.on and RUNNING) then break end
            pcall(LAG.one, d)
            if i % 1500 == 0 then task.wait() end
        end
    end)
end

