track(RunService.Heartbeat:Connect(function()
    if not RUNNING then return end
    local h = hum()
    local r = hrp()
    if not (h and r) then return end
    if PL.ws and not h.SeatPart and h.WalkSpeed ~= PL.wsVal then h.WalkSpeed = PL.wsVal end
    if PL.fly and not h.SeatPart and not S.gliding then
        PL.flying = true
        h.PlatformStand = true
        local move = h.MoveDirection
        local up = 0
        if PL.UIS:IsKeyDown(Enum.KeyCode.Space) or h.Jump then up = up + 1 end
        if PL.UIS:IsKeyDown(Enum.KeyCode.LeftControl) or PL.UIS:IsKeyDown(Enum.KeyCode.Q) then up = up - 1 end
        local cam = workspace.CurrentCamera
        local dir = move
        if cam then
            local cf = cam.CFrame
            local fl = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
            local fr = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)
            if fl.Magnitude > 0.05 and fr.Magnitude > 0.05 and move.Magnitude > 0.05 then
                dir = cf.LookVector * move:Dot(fl.Unit) + cf.RightVector * move:Dot(fr.Unit)
            end
            if fl.Magnitude > 0.05 then r.CFrame = CFrame.lookAt(r.Position, r.Position + fl) end
        end
        dir = dir + Vector3.new(0, up, 0)
        r.AssemblyLinearVelocity = dir.Magnitude > 0.05 and dir.Unit * PL.flySpeed or Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
    elseif PL.flying then
        PL.flying = false
        h.PlatformStand = false
    end
end))
onClean(function()
    local h = hum()
    if h and PL.flying then h.PlatformStand = false end
end)

