                    Opt.de_drcar:SetValues(labs)
                    local lab = DR.pick and DR.labelOf(DR.pick)
                    if not lab then
                        DR.pick = DR.list[1] and DR.list[1].id or nil
                        lab = DR.pick and DR.labelOf(DR.pick) or labs[1]
                    end
                    Opt.de_drcar:SetValue(lab)
                end)
            end
        end
    end)

end)

