    local Sv = Tabs.Settings:AddLeftGroupbox("Server", "server")
    Sv:AddButton({ Text = "Rejoin", Func = function() pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, lp) end) end })
    Sv:AddButton({ Text = "Server Hop", Func = function()
        task.spawn(function()
            local ok, body = pcall(function() return game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Asc&limit=100") end)
            if not ok then notify("Couldn't load servers") return end
            local okd, dat = pcall(function() return HttpService:JSONDecode(body) end)
            for _, s in ipairs(okd and dat and dat.data or {}) do
                if s.id ~= game.JobId and num(s.playing) < num(s.maxPlayers) then
                    pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, s.id, lp) end)
                    return
                end
            end
            notify("No other servers found")
        end)
    end })
end)

task.spawn(function()
    local lastPlay, lastQuest, lastInc = 0, 0, 0
    while RUNNING do
        local now = os.clock()
        if on("de_playtime") and now - lastPlay > 30 then lastPlay = now pcall(RW.playtime) end
        if on("de_quests") and now - lastQuest > 25 then lastQuest = now pcall(RW.quests) end
        if on("de_incent") and now - lastInc > 300 then lastInc = now pcall(function() invoke("IncentivesClaimReward") fire("ClaimRewards") end) end
        task.wait(2)
    end
end)

task.spawn(function()
    S.startCash = cash()
    local t0 = os.clock()
    while RUNNING do
        pcall(function()
            local mins = math.floor((os.clock() - t0) / 60)
            if (S.startCash or 0) <= 0 then S.startCash = cash() end
            local gain = cash() - (S.startCash or 0)
            local head = string.format("Session %dm  ·  +$%s", mins, abbrev(math.max(gain, 0)))
            pcall(function() labels.rob:SetText((S.status.rob or (on("de_atm") and "Starting" or "Off")) .. string.format("\nRobbed %d  ·  Cashed %d  ·  Escaped %d", A.busts, A.cashouts, A.escapes or 0) ..(A.lastFail and ("\nLast fail: " .. A.lastFail) or "")) end)
            pcall(function() labels.del:SetText((S.status.del or (on("de_delivery") and "Starting" or "Off")) .. "\nDelivered " .. D.done .. (D.fail and ("  ·  last: " .. tostring(D.fail)) or "")) end)
            pcall(function() labels.pol:SetText((S.status.pol or ((on("de_scenes") or on("de_arrest")) and "Starting" or "Off")) .. string.format("\nScenes %d  ·  Arrests %d", P.cleared, P.arrests) .. (P.lastFail and ("\nLast fail: " .. P.lastFail) or "")) end)
            pcall(function() labels.drive:SetText((S.status.drive or (on("de_drive") and "Starting" or "Off")) .. "\n" .. head .. (DR.lastFail and ("\nLast fail: " .. DR.lastFail) or "")) end)
            pcall(function() labels.race:SetText((S.status.race or (on("de_race") and "Starting" or "Off")) .. "\nRaces done " .. RC.runs .. (RC.lastFail and ("\nLast fail: " .. RC.lastFail) or "")) end)
            local c = V.ctrl()
            pcall(function() labels.car:SetText(c and string.format("%d mph", math.floor(num(c.SpeedMPH))) or "Not driving") end)
            pcall(function() labels.rw:SetText(head) end)
        end)
        task.wait(0.5)
    end
end)

local function unload()
    pcall(function() for _, k in ipairs(FARMS) do if on(k) then Toggles[k]:SetValue(false) end end end)
    pcall(T.stop)
    pcall(function() if _G.__CW_DE_CLEAN then _G.__CW_DE_CLEAN() end end)
    pcall(function() Library:Unload() end)
end
